using System;using System.Collections.Generic;using AutocatBridge;
class RuntimeLogicTests {
 static void Main(){var rows=new List<object[]>();for(int i=0;i<100;i++)rows.Add(new object[]{null,null,i});var owned=new HashSet<int>(new[]{5,33,77});var bound=new List<int>();var removed=new List<int>();int cursor=0,calls=0,retired=0;
  for(int pass=0;pass<4;pass++){int before=calls;retired+=InventoryHandoff.ReconcileSlice(rows,ref cursor,32,item=>{calls++;return owned.Contains((int)item);},entry=>entry[2],item=>bound.Add((int)item),entry=>removed.Add((int)entry[2]));if(calls-before>32)throw new Exception("Slice exceeded bound");}
  if(retired!=3||rows.Count!=97||bound.Count!=3||removed.Count!=3||rows.Exists(r=>owned.Contains((int)r[2])))throw new Exception("Reconciliation result");
  int emptyCursor=99;var empty=new List<object[]>();if(InventoryHandoff.ReconcileSlice(empty,ref emptyCursor,32,x=>false,x=>null,x=>{},x=>{})!=0||emptyCursor!=0)throw new Exception("Empty cursor");
  var selected=new Dictionary<string,int>();if(!InventoryHandoff.BadgeState(true,"skin",10,selected))throw new Exception("Authoritative badge lost without override");selected["skin"]=20;if(InventoryHandoff.BadgeState(true,"skin",10,selected)||!InventoryHandoff.BadgeState(false,"skin",20,selected))throw new Exception("Owned to temporary transition shows two badges");selected["skin"]=-1;if(InventoryHandoff.BadgeState(true,"skin",10,selected)||InventoryHandoff.BadgeState(false,"skin",20,selected))throw new Exception("Temporary clear leaves a badge selected");selected["skin"]=10;if(!InventoryHandoff.BadgeState(true,"skin",10,selected)||InventoryHandoff.BadgeState(false,"skin",20,selected))throw new Exception("Temporary to owned transition invalid");
  if(!InventoryHandoff.NeedsOwnedReequip(true,20,10,false))throw new Exception("Owned reselect after temporary must repair native toggle");if(!InventoryHandoff.NeedsOwnedReequip(true,-1,10,false))throw new Exception("Owned reselect after virtual clear must repair native toggle");if(InventoryHandoff.NeedsOwnedReequip(false,0,10,false)||InventoryHandoff.NeedsOwnedReequip(true,10,10,false)||InventoryHandoff.NeedsOwnedReequip(true,20,10,true))throw new Exception("Owned reselect repair triggered outside stale-authoritative transition");
  Console.WriteLine("PASS: bounded ownership reconciliation and exclusive owned/temporary selection transitions");}
}
